/// Inputs of `linode.instance`; build with [`Instance::builder`] or [`Stack::linode_instance`].
#[derive(Serialize, Builder)]
#[builder(start_fn(name = builder), finish_fn(name = build), builder_type = InstanceBuilder, state_mod = instance_state)]
pub struct InstanceInputs<'a> {
    /// Resource name; with the type it forms the URN `linode.instance:<name>`.
    #[builder(start_fn, into)]
    #[serde(skip)]
    pub resource_name: String,
    #[builder(field)]
    #[serde(skip)]
    stack: Option<&'a mut Stack>,
    #[builder(field)]
    #[serde(skip)]
    depends_on: Vec<Urn>,
    #[builder(field)]
    #[serde(skip)]
    triggers: Vec<Urn>,
    #[builder(field)]
    #[serde(skip)]
    protect: bool,
    /// Unique name shown in the Linode Cloud Manager; an existing instance with this label is adopted instead of created.
    #[builder(into)]
    pub label: Input<String>,
    /// Data-center slug, e.g. `us-east` or `eu-central` (`linode-cli regions list`).
    #[builder(into)]
    pub region: Input<InstanceRegion>,
    /// Plan slug that sets CPU/RAM/disk, e.g. `g6-nanode-1`; changing it resizes the instance in place (with a reboot).
    #[builder(into)]
    #[serde(rename = "type")]
    pub r#type: Input<InstanceType>,
    #[builder(setters(vis = "", name = source_internal))]
    #[serde(flatten)]
    pub source: Option<InstanceSource>,
    /// Root password set at first boot; never read back from the API.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub root_pass: Option<Input<String>>,
    /// Public SSH keys written to root's `authorized_keys` at first boot.
    #[builder(setters(vis = "", name = authorized_keys_internal))]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub authorized_keys: Option<Input<Vec<Input<String>>>>,
    /// Linode account usernames whose profile SSH keys are installed at first boot.
    #[builder(setters(vis = "", name = authorized_users_internal))]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub authorized_users: Option<Input<Vec<Input<String>>>>,
    /// Local disk encryption policy selected when the instance is created.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub disk_encryption: Option<Input<InstanceDiskEncryption>>,
    /// Primary boot disk size in MiB; remaining plan storage stays unallocated.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub boot_size: Option<Input<i64>>,
    /// Swap disk size in MiB (Linode defaults to 512).
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub swap_size: Option<Input<i64>>,
    /// Networking model selected at creation; this cannot be changed in place.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub interface_generation: Option<Input<InstanceInterfaceGeneration>>,
    /// Linode or legacy interface definitions passed to the create API.
    #[builder(setters(vis = "", name = interfaces_internal))]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub interfaces: Option<Input<Vec<Input<serde_json::Value>>>>,
    /// An unassigned reserved public IPv4 address to assign at creation.
    #[builder(setters(vis = "", name = ipv4_internal))]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ipv4: Option<Input<Vec<Input<String>>>>,
    /// Kernel id selected for the initial configuration profile.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub kernel: Option<Input<String>>,
    /// Enable Network Helper for Linode-interface networking.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub network_helper: Option<Input<bool>>,
    /// Placement group to join at creation; it must be in the selected region.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub placement_group_id: Option<Input<i64>>,
    /// StackScript id to run during image deployment.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stackscript_id: Option<Input<i64>>,
    /// StackScript UDF values; treated as sensitive because they commonly contain credentials.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stackscript_data: Option<Input<serde_json::Value>>,
    /// Free-form labels for grouping and filtering in the Cloud Manager.
    #[builder(setters(vis = "", name = tags_internal))]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Input<Vec<Input<String>>>>,
    /// Also assign a private (192.168.x.x) address reachable from other Linodes in the same region.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub private_ip: Option<Input<bool>>,
    /// Enrol in the paid Linode Backup Service (daily snapshots).
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub backups_enabled: Option<Input<bool>>,
    /// Paid Backup Service schedule.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub backup_schedule: Option<BackupSchedule>,
    /// Prefer live migration or power-off/on during host maintenance.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub maintenance_policy: Option<Input<InstanceMaintenancePolicy>>,
    /// Enable Lassie to restart an instance that powers off unexpectedly.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub watchdog_enabled: Option<Input<bool>>,
    /// Cloud Manager alert thresholds.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub alerts: Option<InstanceAlerts>,
    /// Keep the instance powered on (`true`) or shut down (`false`).
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub booted: Option<Input<bool>>,
    /// Id of a Cloud Firewall to attach at creation; prefer `linode.firewall(linodes=...)` for attachments that can change later.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub firewall_id: Option<Input<i64>>,
    /// cloud-init user data (e.g. a `#cloud-config` document) run on first boot; base64-encoded for you.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub user_data: Option<Input<String>>,
    /// Login user for the `connection` output; not sent to Linode.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ssh_user: Option<Input<String>>,
    /// Seconds `host.*` resources keep retrying the first SSH connection while the instance finishes booting.
    #[builder(into)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub connect_timeout_secs: Option<Input<i64>>,
}

impl Instance {
    /// Start declaring a `linode.instance` named `name`; finish with `.build()` and `stack.add(..)`.
    pub fn builder(name: impl Into<String>) -> InstanceBuilder<'static> {
        InstanceInputs::builder(name)
    }
}

