    /// Order this resource after `h` even though no input references it.
    pub fn depends_on<R>(mut self, h: &Handle<R>) -> Self {
        self.depends_on.push(h.urn().clone());
        self
    }

    /// Re-apply this resource whenever `h` changes in the same run.
    pub fn triggered_by<R>(mut self, h: &Handle<R>) -> Self {
        self.triggers.push(h.urn().clone());
        self
    }

    /// Refuse to delete or replace this resource.
    pub fn protect(mut self) -> Self {
        self.protect = true;
        self
    }
