impl<'a, S: instance_state::IsComplete> InstanceBuilder<'a, S> {
    /// Register the resource with the stack this builder was started from.
    pub fn add(mut self) -> anyhow::Result<Handle<Instance>> {
        let stack = self.stack.take().ok_or_else(|| anyhow::anyhow!("linode.instance: builder was not started from a Stack; use .build() and stack.add(..)"))?;
        stack.add(self.build())
    }
}

impl Declare for InstanceInputs<'_> {
    type Type = Instance;

    fn into_decl(self) -> anyhow::Result<ResourceDecl> {
        let inputs = crate::stack::strip_nulls(serde_json::to_value(&self)?);
        let mut decl = ResourceDecl::new("linode.instance", &self.resource_name, inputs);
        decl.depends_on = self.depends_on;
        decl.triggers = self.triggers;
        decl.protect = self.protect;
        Ok(decl)
    }
}

impl Stack {
    /// Declare a `linode.instance`; finish with `.add()`.
    pub fn linode_instance(&mut self, name: impl Into<String>) -> InstanceBuilder<'_> {
        let mut b = InstanceInputs::builder(name);
        b.stack = Some(self);
        b
    }
}

